  VALUES ('39b7543a-0164-561a-9d61-2e472ff5ef70', '79ce8243-eb8c-5c6f-80fa-e9b93d57490e', 27, 1, 'single_choice', 'According to Paragraph A, what is the fundamental goal of deliberative democratic forums?', '[{"letter": "A", "text": "To replace elected politicians with certified academic experts."}, {"letter": "B", "text": "To create policy decisions through inclusive and reasoned citizen discussion."}, {"letter": "C", "text": "To accelerate government decision-making by eliminating public voting."}, {"letter": "D", "text": "To ensure that technical specialists have the final authority over legislation."}]'::jsonb);
INSERT INTO test_answers (question_id, accepted) VALUES ('39b7543a-0164-561a-9d61-2e472ff5ef70', '["B"]'::jsonb);
INSERT INTO test_questions (id, section_id, qnumber, position, type, prompt, options)
  VALUES ('97c5bfcf-2abb-5b93-989a-f7e6dff9a4d5', '79ce8243-eb8c-5c6f-80fa-e9b93d57490e', 28, 2, 'single_choice', 'What distinguishes hermeneutical injustice from testimonial injustice?', '[{"letter": "A", "text": "It involves the direct physical intimidation of marginalized speakers in forums."}, {"letter": "B", "text": "It occurs when a speaker''s statements are judged solely on statistical data."}, {"letter": "C", "text": "It stems from a structural lack of shared concepts to explain social experiences."}, {"letter": "D", "text": "It results exclusively from deliberate financial corruption within political parties."}]'::jsonb);
