  VALUES ('2df08dcf-2d64-5d65-b6fa-2d2cd87bb695', '6ea030ec-030d-5dc2-b5aa-f97191a4548e', 29, 3, 'single_choice', 'Why is Kolmogorov complexity considered "uncomputable"?', '[{"letter": "A", "text": "No computer has sufficient memory to store large binary strings."}, {"letter": "B", "text": "It relies on quantum processes that cannot be measured accurately."}, {"letter": "C", "text": "It is constrained by the impossibility of solving the Halting Problem."}, {"letter": "D", "text": "The mathematical formulas used in information theory are fundamentally incorrect."}]'::jsonb);
