  VALUES ('0a42973f-6229-56f7-8a0b-25bf694c7c63', '92f0f2c6-f2c5-5ebc-a86b-f16899326de9', 27, 1, 'single_choice', 'Why were classical biophysicists initially skeptical of quantum effects occurring inside living cells?', '[{"letter": "A", "text": "Living organisms lack the chemical compounds necessary to produce electrons."}, {"letter": "B", "text": "Cells operate at warm temperatures and contain chaotic fluids that cause decoherence."}, {"letter": "C", "text": "Quantum mechanics was thought to apply only to celestial bodies and astronomy."}, {"letter": "D", "text": "Biological structures are too small to be analyzed by physical instruments."}]'::jsonb);
