  VALUES ('fb38a95b-9c57-521b-9c9c-b37556c38490', 'dfba983a-d0a2-5e7c-8056-9b88fc360dd2', 27, 1, 'single_choice', 'According to the modern evolutionary synthesis described in Paragraph A:', '[{"letter": "A", "text": "environmental stress can directly modify DNA sequences in a deliberate direction."}, {"letter": "B", "text": "acquired characteristics developed during a lifetime cannot be inherited by offspring."}, {"letter": "C", "text": "physical traits are determined entirely by non-coding RNA molecules."}, {"letter": "D", "text": "natural selection plays a minor role in driving biological evolution."}]'::jsonb);
