INSERT INTO test_questions (id, section_id, qnumber, position, type, prompt, options)
  VALUES ('83966785-acb9-5adc-85b9-8280282cce69', 'dfba983a-d0a2-5e7c-8056-9b88fc360dd2', 29, 3, 'single_choice', 'Why was genuine transgenerational epigenetic inheritance in mammals long thought impossible?', '[{"letter": "A", "text": "Mammals do not possess any non-coding RNA in their cells."}, {"letter": "B", "text": "Epigenetic marks are thoroughly erased and reset during two distinct developmental stages."}, {"letter": "C", "text": "DNA methylation occurs only in plants and cold-blooded animals."}, {"letter": "D", "text": "Sperm cells are incapable of carrying epigenetic information."}]'::jsonb);
