  VALUES ('6e01a1a4-3534-5844-9fb2-8c37deb8db7b', '6061f312-5430-5972-977d-e2a80071de7f', 27, 1, 'single_choice', 'Under classical Darwinian selection described in Paragraph A, biological altruism was considered a paradox because:', '[{"letter": "A", "text": "animals lack the cognitive capacity to remember other individuals."}, {"letter": "B", "text": "selfish behaviors were expected to outcompete costly helpful behaviors."}, {"letter": "C", "text": "environmental resources are always abundant enough to share."}, {"letter": "D", "text": "all organisms share the exact same genetic relatedness coefficient."}]'::jsonb);
