INSERT INTO test_questions (id, section_id, qnumber, position, type, prompt, options)
  VALUES ('1e99d753-3f56-5589-a2e1-d3006fd78580', 'ebafbaf6-40ed-535f-8353-7f96f8b7d6de', 31, 5, 'single_choice', 'How do modern physicists like Deutsch and Wallace address the probability problem in Many-Worlds?', '[{"letter": "A", "text": "By proving that the Born rule is completely false and should be abandoned."}, {"letter": "B", "text": "By showing that rational agents must evaluate branch possibilities using wave amplitudes."}, {"letter": "C", "text": "By demonstrating that some branches are destroyed immediately after splitting."}, {"letter": "D", "text": "By creating physical machines that send messages between parallel universes."}]'::jsonb);
