  VALUES ('aac79a77-b90b-5797-81f9-662b90de8946', '61a08da8-2a7c-5dde-820f-e4930b00c716', 27, 1, 'single_choice', 'According to Paragraph A, how does human cooperation differ fundamentally from that of social insects?', '[{"letter": "A", "text": "Human cooperation is restricted exclusively to immediate genetic family members."}, {"letter": "B", "text": "Humans routinely collaborate on a large scale with individuals who are not genetic relatives."}, {"letter": "C", "text": "Human societies operate without any division of labor or specialized roles."}, {"letter": "D", "text": "Animals use formal legal systems to punish free-riding members of their groups."}]'::jsonb);
