  VALUES ('ec8e27ff-cea9-5b54-99d2-04911e415949', '4a50d7a6-c6a7-5440-8889-4647f94e604f', 27, 1, 'single_choice', 'According to Paragraph B, what is the key feature of the "Condorcet Paradox"?', '[{"letter": "A", "text": "Voters refuse to participate in elections if there are more than two candidates."}, {"letter": "B", "text": "Individual rational preferences can result in a circular and contradictory group preference."}, {"letter": "C", "text": "Dictatorial leaders always emerge whenever majority voting is used in small committees."}, {"letter": "D", "text": "Sincere voting produces identical outcomes across all historical elections."}]'::jsonb);
