INSERT INTO test_questions (id, section_id, qnumber, position, type, prompt, options)
  VALUES ('2bee9c7f-8f40-53bc-9fde-a010f4ebfc35', '70b20611-fcf8-5511-a1df-797b085de6e9', 31, 5, 'single_choice', 'How does Radical Constructivism answer the accusation that it promotes solipsism?', '[{"letter": "A", "text": "By arguing that humans can walk through solid walls if they believe in constructivism."}, {"letter": "B", "text": "By showing that conceptual models are strictly constrained when they collide with reality."}, {"letter": "C", "text": "By rejecting all empirical experiments conducted in physics laboratories."}, {"letter": "D", "text": "By claiming that scientific truth is decided entirely by political voting."}]'::jsonb);
