  VALUES ('1fd7e5ee-a0ba-5564-b575-f10aa589499a', 'bffa7c45-25bf-5fce-a817-a3348d6a5875', 27, 1, 'single_choice', 'According to Paragraph A, what is the defining principle of utilitarianism?', '[{"letter": "A", "text": "Moral choices must follow absolute religious rules without exception."}, {"letter": "B", "text": "Actions should be evaluated entirely by the overall outcomes they produce."}, {"letter": "C", "text": "Human emotions should be ignored completely in personal legal disputes."}, {"letter": "D", "text": "Individuals have a natural duty to prioritize their own financial wealth."}]'::jsonb);
