  VALUES ('b75a8d04-42cd-54e4-a368-a893bd8d701e', 'd23e60cb-5da4-5bfe-a3ef-5cacf123e0a2', 27, 1, 'single_choice', 'According to Paragraph B, Hamilton’s Rule ($rB > C$) explains that altruism will spread if:', '[{"letter": "A", "text": "direct offspring produce more food than the group consumes."}, {"letter": "B", "text": "the cost to the actor is smaller than the benefit to a relative multiplied by relatedness."}, {"letter": "C", "text": "an organism stops interacting with all genetic family members."}, {"letter": "D", "text": "the government provides financial subsidies for large families."}]'::jsonb);
INSERT INTO test_answers (question_id, accepted) VALUES ('b75a8d04-42cd-54e4-a368-a893bd8d701e', '["B"]'::jsonb);
