  VALUES ('ada938fa-ef1d-52fd-8f18-79d31b2e364f', 'd07a9ed3-40fb-58b2-97bc-b80db3192000', 28, 2, 'single_choice', 'What was a major limitation of classical game theory mentioned in Paragraph B?', '[{"letter": "A", "text": "It could only be used to calculate moves in the game of chess."}, {"letter": "B", "text": "It required computers that were too expensive for university departments."}, {"letter": "C", "text": "It struggled to explain how real populations select between multiple competing equilibria."}, {"letter": "D", "text": "It proved that human beings never cooperate under any circumstances."}]'::jsonb);
