  VALUES ('0fe8650f-455b-594b-9d2c-fa4b76ddc8b3', 'd07a9ed3-40fb-58b2-97bc-b80db3192000', 29, 3, 'single_choice', 'How does Evolutionary Game Theory (EGT) differ from classical game theory?', '[{"letter": "A", "text": "It replaces conscious rational calculation with natural selection and population dynamics."}, {"letter": "B", "text": "It assumes all players have infinite computational power."}, {"letter": "C", "text": "It requires governments to enforce every strategic decision."}, {"letter": "D", "text": "It focuses exclusively on games involving financial stock investments."}]'::jsonb);
