  VALUES ('fded216d-07a1-54fc-8c9d-0544dcfe078c', '6ace75cd-66df-583a-a132-e448d8264a50', 30, 4, 'single_choice', 'The "Self-Refutation Argument" raised by critics against eliminativism contends that:', '[{"letter": "A", "text": "eliminativists require a belief in their own theory to argue that beliefs do not exist."}, {"letter": "B", "text": "neuroscience experiments are too dangerous to conduct on human subjects."}, {"letter": "C", "text": "the human brain contains too many blood vessels to allow physical calculations."}, {"letter": "D", "text": "ancient Greek plays prove that oxygen does not exist in the atmosphere."}]'::jsonb);
