INSERT INTO test_questions (id, section_id, qnumber, position, type, prompt, options)
  VALUES ('e9c2ecbc-fe40-549a-a9cd-0dd91c8d654e', '6ace75cd-66df-583a-a132-e448d8264a50', 31, 5, 'single_choice', 'How does Paul Churchland answer the self-refutation critique in Paragraph G?', '[{"letter": "A", "text": "By admitting that eliminative materialism is a completely false theory."}, {"letter": "B", "text": "By comparing it to a vitalist who falsely assumes \"vital spirits\" are necessary to speak."}, {"letter": "C", "text": "By proving that no human beings have ever spoken words in history."}, {"letter": "D", "text": "By demonstrating that computers cannot process language."}]'::jsonb);
