  VALUES ('eb8d29a1-09c8-5e81-8030-f324353b802c', 'd994ce58-8a2e-5d14-a677-d6bd43d394a5', 30, 4, 'single_choice', 'Why is Horn 2 (the tracking account) rejected by debunkeurs in Paragraph D?', '[{"letter": "A", "text": "Natural selection fully explains moral beliefs without needing extra metaphysical facts."}, {"letter": "B", "text": "Ancient human skeletons show no signs of brain development."}, {"letter": "C", "text": "DNA cannot be sequenced by modern laboratory tools."}, {"letter": "D", "text": "Animals refuse to cooperate in natural environments."}]'::jsonb);
