  VALUES ('c0576eca-b39b-5767-8c00-3a901755fa5d', 'd994ce58-8a2e-5d14-a677-d6bd43d394a5', 31, 5, 'single_choice', 'How does Charles Darwin’s hive-bee thought experiment in Paragraph E support the debunking view?', '[{"letter": "A", "text": "It proves that bees can speak human languages."}, {"letter": "B", "text": "It shows that moral intuitions are contingent on evolutionary history and could have been completely different."}, {"letter": "C", "text": "It proves that human beings should live in hives."}, {"letter": "D", "text": "It demonstrates that female bees possess human moral souls."}]'::jsonb);
