  VALUES ('30c16689-edde-5b7e-a7a5-3cdb808bebf4', 'bf941686-48ef-55e7-a3bc-196a9303d661', 27, 1, 'single_choice', 'According to classical procedural democracy described in Paragraph A, democratic legitimacy comes from:', '[{"letter": "A", "text": "the mathematical efficiency of government tax collection agencies."}, {"letter": "B", "text": "the fair and equal nature of the voting procedure itself."}, {"letter": "C", "text": "the physical strength and military training of elected leaders."}, {"letter": "D", "text": "the number of scientific research laboratories in a nation."}]'::jsonb);
