  VALUES ('3c084e6e-8643-5ddb-94b5-38d64c0c5dfb', '2a8d1e5f-44a8-507e-9606-da96c85701df', 31, 5, 'single_choice', 'How does G.', '[{"letter": "A", "text": "Cohen defend luck egalitarianism against Anderson''s critique in Paragraph G?"}, {"letter": "A", "text": "By arguing that computers should manage all government elections."}, {"letter": "B", "text": "By maintaining that pure justice is strictly concerned with eliminating unchosen inequalities."}, {"letter": "C", "text": "By proving that social respect is the only virtue that matters in politics."}, {"letter": "D", "text": "By claiming that human beings have no voluntary choices."}]'::jsonb);
