  VALUES ('a4f1bff1-9897-5202-ae40-2216f7a54432', 'c07e84ef-8716-5da3-9f00-d07bac16895f', 27, 1, 'single_choice', 'In the Sleeping Beauty protocol described in Paragraph B, what happens if the coin lands Tails?', '[{"letter": "A", "text": "Beauty is awakened only on Wednesday morning."}, {"letter": "B", "text": "Beauty is awakened on both Monday and Tuesday, with memory erasure between."}, {"letter": "C", "text": "Beauty is never put to sleep and leaves the lab immediately."}, {"letter": "D", "text": "Beauty is given a permanent memory-enhancing medication."}]'::jsonb);
