  VALUES ('4b9ae982-b824-5b75-a6e0-b7b55a74d5f1', '241366d1-04d2-5296-80f9-1e35c8b767d9', 29, 3, 'single_choice', 'In the "Bank Cases" thought experiment, why does Hannah lose knowledge in Case 2 (High Stakes)?', '[{"letter": "A", "text": "She suffered a medical head injury that erased her memory."}, {"letter": "B", "text": "The catastrophic practical risk of being wrong raises the epistemic standard."}, {"letter": "C", "text": "The bank building was demolished by city planners on Friday night."}, {"letter": "D", "text": "She forgot how to drive her car to the bank."}]'::jsonb);
