  VALUES ('a6a830eb-c9a2-5f5f-98b9-baee42c257fa', '241366d1-04d2-5296-80f9-1e35c8b767d9', 30, 4, 'single_choice', 'In Epistemic Contextualism, how are the Bank Cases explained in Paragraph E?', '[{"letter": "A", "text": "Banks change their operating hours every week."}, {"letter": "B", "text": "High stakes alter the semantic standards of the word \"knows\" used by the speaker."}, {"letter": "C", "text": "Hannah never had any memory of visiting the bank."}, {"letter": "D", "text": "Human eyes cannot see paper bank checks clearly."}]'::jsonb);
